import os
import torch


class Config:
    # ==========================================
    # Project & Paths
    # ==========================================
    PROJECT_NAME = "idea_7"
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Working Directory for Caching and Models
    WORKING_DIR = os.path.join("./working", PROJECT_NAME)
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")

    # Metadata File Paths (Generated by previous steps)
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test.csv")

    # Output Paths
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Audio Processing Parameters
    # ==========================================
    SAMPLE_RATE = 16000
    DURATION = 1.0  # seconds
    NUM_SAMPLES = int(SAMPLE_RATE * DURATION)

    # Mel Spectrogram Settings
    N_MELS = 64
    F_MIN = 20
    F_MAX = 8000

    # Multi-Resolution Configuration
    # We map time-frequency trade-offs to the channel dimension (3 channels).
    # To stack them, the time dimension must be identical, so we fix HOP_LENGTH.
    HOP_LENGTH = 160  # 10ms

    # Define the 3 resolutions for the channels
    # n_fft is chosen to be the next power of 2 >= win_length
    RESOLUTIONS = [
        {
            "name": "short",
            "win_length": 320,
            "n_fft": 512,
        },  # ~20ms window (High Time Res)
        {"name": "medium", "win_length": 640, "n_fft": 1024},  # ~40ms window (Balanced)
        {
            "name": "long",
            "win_length": 960,
            "n_fft": 2048,
        },  # ~60ms window (High Freq Res)
    ]

    # ==========================================
    # Label Configuration
    # ==========================================
    # The 10 commands + silence + unknown
    LABELS = [
        "yes",
        "no",
        "up",
        "down",
        "left",
        "right",
        "on",
        "off",
        "stop",
        "go",
        "silence",
        "unknown",
    ]
    NUM_CLASSES = len(LABELS)
    LABEL2ID = {label: i for i, label in enumerate(LABELS)}
    ID2LABEL = {i: label for i, label in enumerate(LABELS)}

    # ==========================================
    # Model Architecture
    # ==========================================
    # Backbone: Selective Kernel ResNet
    BACKBONE = "skresnet34"
    PRETRAINED = True
    IN_CHANNELS = 3  # Corresponds to the 3 resolutions

    # Neck: BiGRU
    HIDDEN_DIM = 256

    # Head: Multi-Head Attention Pooling
    NUM_ATTENTION_HEADS = 4
    DROPOUT = 0.3

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42
    BATCH_SIZE = 128  # A100 40GB allows large batches
    NUM_WORKERS = 12  # Matches vCPU count
    EPOCHS = 25
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-2

    # Scheduler (Cosine Annealing)
    T_MAX = EPOCHS
    ETA_MIN = 1e-6

    # Early Stopping
    PATIENCE = 5

    # Augmentation (SpecAugment)
    # Applied on the cached spectrograms
    FREQ_MASK_PARAM = 10
    TIME_MASK_PARAM = 20  # Max time mask length (approx 20% of 1s)

    # ==========================================
    # Execution Flags
    # ==========================================
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 200  # Number of samples to use when DEBUG is True

    DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    @classmethod
    def setup_directories(cls):
        """Creates the necessary working and submission directories."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
